import{f as o,o as e,c as a,aj as u}from"./chunks/framework.CJTJR_Xv.js";const d=JSON.parse('{"title":"02 创建一个游戏的开始界面","description":"在 UE5 中创建一个游戏的开始界面，包含菜单和按钮的设计与实现。","frontmatter":{"title":"02 创建一个游戏的开始界面","date":"2026-06-03T00:00:00.000Z","description":"在 UE5 中创建一个游戏的开始界面，包含菜单和按钮的设计与实现。","tags":["UE5","游戏开发","引擎学习"]},"headers":[],"relativePath":"series/UE5 学习笔记/02创建一个游戏的开始界面.md","filePath":"series/UE5 学习笔记/02创建一个游戏的开始界面.md","lastUpdated":1788599939000}'),q={name:"series/UE5 学习笔记/02创建一个游戏的开始界面.md"};function r(l,t,i,s,_,n){return e(),a("div",null,t[0]||(t[0]=[u('<h1 id="_02-创建一个游戏的开始界面" tabindex="-1">02 创建一个游戏的开始界面 <a class="header-anchor" href="#_02-创建一个游戏的开始界面" aria-label="Permalink to &quot;02 创建一个游戏的开始界面&quot;">​</a></h1><p>在我们设计与开发游戏的过程中，开始界面是玩家进入游戏的第一印象，对于我们开发者来说，我们也更希望有个快速启动项目的入口。 反正我是面对着一大堆的资源和代码，感觉有个开始界面会更好开始下面的开发。开始界面可以后期再进行美术设计和功能完善。</p><h2 id="第一步-创建一个新的关卡" tabindex="-1">第一步：创建一个新的关卡 <a class="header-anchor" href="#第一步-创建一个新的关卡" aria-label="Permalink to &quot;第一步：创建一个新的关卡&quot;">​</a></h2><p>UE5 的设计是基于关卡的，我们的游戏世界就是由一个个关卡组成的，所以我们首先需要创建一个新的空关卡来作为我们的开始界面。</p><p>在 Content/myGame 目录下，右键点击选择 &quot;New Folder&quot;，命名为 &quot;Maps&quot;。然后进入 Maps 文件夹，右键点击选择 &quot;New Level&quot;，命名为 &quot;L_StartMenu&quot;。</p><details class="details custom-block"><summary>UE5 的命名规范</summary><p>在 UE5 中，为了直观的识别资源的类型，我们通常会在资源名称前加上一个前缀。</p><p>例如，关卡我们使用 &quot;L_&quot;，蓝图类使用 &quot;BP_&quot;，材质使用 &quot;M_&quot; ,&quot;WBP_&quot; 代表 Widget Blueprint 等等。</p><p>这种命名规范可以帮助我们更快地找到和管理资源。</p><p>同样的，在编写代码时，我们也会使用类似的命名规范来区分不同类型的变量和函数。</p><p>常见的类类型根据 UE5 的设计，分为以下几类：</p><ul><li>Actor：游戏世界中的对象，例如角色、道具、环境等，通常以 &quot;A&quot; 开头，例如 &quot;APlayerCharacter&quot;。</li><li>Component：Actor 的组成部分，例如碰撞组件、渲染组件等，通常以 &quot;C&quot; 开头，例如 &quot;CHealthComponent&quot;。</li><li>Widget：用户界面元素，例如按钮、文本框等，通常以 &quot;W&quot;开头，例如 &quot;WMainMenu&quot;。</li></ul><p>对于普通的类，我也建议使用项目名称作为前缀，例如 &quot;MyGame&quot; 项目的类可以命名为 &quot;MyGamePlayerController&quot;或&quot;MGCharacter&quot;,这样可以避免与其他项目的类名冲突。</p></details><h2 id="第二步-设置开始界面为默认关卡" tabindex="-1">第二步：设置开始界面为默认关卡 <a class="header-anchor" href="#第二步-设置开始界面为默认关卡" aria-label="Permalink to &quot;第二步：设置开始界面为默认关卡&quot;">​</a></h2><p>创建好关卡后，我们需要将它设置为游戏的默认关卡，这样当我们运行游戏时，就会直接进入这个开始界面。 在 UE5 的编辑器中，点击菜单栏的 &quot;编辑&quot;，选择 &quot;项目设置&quot;。在左侧的设置列表中，找到 &quot;地图和模式&quot; 选项。在 &quot;默认地图&quot; 部分，将 &quot;编辑器启动地图&quot; 和 &quot;游戏默认地图&quot; 都设置为我们刚才创建的 &quot;L_StartMenu&quot;。</p>',8)]))}const c=o(q,[["render",r]]);export{d as __pageData,c as default};
